\section{Derivation of Flight size PDF solution}

We consider a colloid that is moving between pores of different length $\lambda$. We assume that the length and the diameter are the same. That is, a long pore has also a large diameter. If the colloid enters the pore at a distance $R_c$ from the wall it dives. The probability that the colloid does not dive, that is, that is flies upon entering a pore is denoted by $\alpha_i$. The latter can depend on the properties of the pore, like its length and diameter. The probability $p_n$ that a particle flies exactly along $n$ pores before it dives is given by

\begin{align}
\label{eq:pn}
p_n = \prod\limits_{i = 1}^n \alpha_i (1 - \alpha_{n+1}),
\end{align}

that is, the probability to fly along $n$ pores times the probability to dive at the $n+1$th pore. Thus, the distribution of flight lengths is given by

\begin{align}
\label{eq:p}
p(x) = \left\langle \sum\limits_{n = 0}^\infty \rho_n(x) p_n \right\rangle,
\end{align}

where $\rho_n(x)$ is the distribution of flight distances after $n$ steps,

\begin{align}
\rho_n (x) = \delta(x - \ell_n).
\end{align}

The flight distance $\ell_n$ after $n$ pores is

\begin{align}
\label{eq:ell}
\ell_n = \sum\limits_{i = 1}^n \lambda_i.
\end{align}

The angular brackets denote the average over all colloids. We can write $p(x)$ by using~\eqref{eq:pn} and~\eqref{eq:ell} as

\begin{align}
p(x) = \left\langle \sum\limits_{n = 0}^\infty \delta\left(x - \sum\limits_{i = 1}^n \lambda_i\right) \prod\limits_{i = 1}^n \alpha_i
(1 - \alpha_{n+1}) \right\rangle
\end{align}

\subsection{Constant diving rate and constant pore-length}

We consider the first the case of constant diving rate $\alpha_0$ and pore length $\lambda_0$. Thus, we obtain for $p(x)$

\begin{align}
p(x) = \sum\limits_{n = 0}^\infty \delta\left(x  - n \lambda_0\right) \alpha_0^n
(1 - \alpha_0).
\end{align}

That is, the probability $p_n$ of $x = n \lambda_0$ is

\begin{align}
p_n = \alpha_0^n (1 - \alpha_0) = \exp(n \ln \alpha_0) - \exp[(n + 1) \ln
\alpha_0] = \exp(- x_n/\lambda_c) - \exp(-x_{n+1}/\lambda_c) = H(x_n > \lambda_0),
\end{align}

where we defined $\lambda_c = - \lambda_0/\ln \alpha_0$ For $x \gg \lambda_c$, we can write

\begin{align}
p_n = \frac{\Delta x \exp(-x/\lambda_c)}{\lambda_c},
\end{align}

that is

\begin{align}
p(x) = \frac{p_n}{\Delta x} = \frac{\exp(-x/\lambda_c)}{\lambda_c}.
\end{align}

Thus, it decays exponentially fast on the length scale $\lambda_c = - \lambda_0/\ln \alpha_0$.

\begin{figure}
\includegraphics[width=0.8\textwidth]{S2_flightPDF_lambda_constant.pdf}
\caption{Distribution of flight distances for constant pore length and diving rate.\label{fig1}}
\end{figure}

\subsection{Constant diving rate and exponential pore-length distribution}

We consider the case the $\alpha_i = \alpha_0 = $ constant and $\lambda_i$ exponentially distributed with characteristic scale $\ell_0$. In this case,

\begin{align}
\rho_n(x) = \left(\frac{x}{\ell_0}\right)^{n-1}
\frac{\exp(-x/\ell_0)}{\Gamma(n) \ell_0}.
\end{align}

for $n > 0$. Thus, we obtain for the flight distance distribution

\begin{align}
p(x) = \frac{\exp(-x/\ell_0)}{\ell_0}(1 - \alpha_{0})  \sum\limits_{n =
  1}^\infty \left(\frac{x}{\ell_0}\right)^{n-1}
\frac{\alpha_0^{n}}{\Gamma(n)} + (1 - \alpha_0) \delta(x)
\end{align}

The sum can be written as

\begin{align}
& \sum\limits_{n = 1}^\infty \left(\frac{x}{\ell_0}\right)^{n-1}
\frac{\alpha_0^{n}}{\Gamma(n)} = \left(\frac{x}{\ell_0}\right)^{-1} \sum\limits_{n =
  1}^\infty \left(\frac{x}{\ell_0}\right)^{n}
\frac{\alpha_0^{n}}{\Gamma(n)}
\\
&= \left(\frac{x}{\ell_0}\right)^{-1} \left[\sum\limits_{n =
  0}^\infty \left(\frac{x}{\ell_0}\right)^{n}
\frac{\alpha_0^{n}}{\Gamma(n)} - 1\right] = \left(\frac{x}{\ell_0}\right)^{-1} \left[\exp(x\alpha_0/\ell_0) - 1\right]
\end{align}

Thus, we obtain for $p(x)$

\begin{align}
p(x) = \frac{(1 - \alpha_{0})\exp(- x(1 - \alpha_0)/\ell_0)}{\ell_0}
\left(\frac{x}{\ell_0}\right)^{-1} \left[1 - \exp(-x \alpha_0/\ell_0)\right]
+ (1 - \alpha_0) \delta(x)
\end{align}

The characteristic decay distance here is $\ell_0/(1 - \alpha)$ after which $p(x)$ decays exponentially with distance. For $\ell_0 \ll x \ll \ell_0/(1 - \alpha_0)$ it decays as $x^{-1}$.

\subsection{Variable diving rate and Gamma-distributed pore lengths}

The probability for diving

\begin{align}
\beta(\lambda) = \frac{\pi (\lambda/2)^2 - \pi (\lambda/2-R_c)^2}{\pi (\lambda/2)^2}
H(\lambda/2 - R_c) + H(R_c - \lambda/2).
\end{align}

The probability that the colloid does not dive is then accordingly

\begin{align}
\alpha(\lambda) = 1 - \beta = (1-2 R_c/\lambda)^2
H(\lambda/2 - R_c)  - H(R_c - \lambda/2)
\end{align}

In this case, we obtain for the distribution of flight lengths

\begin{align}
p(x) = \left\langle \sum\limits_{n = 0}^\infty \delta\left(x - \sum\limits_{i = 1}^n \lambda_i\right) \prod\limits_{i = 1}^n (1-2 R_c/\lambda_i)^2
[1 - (1-2 R_c/\lambda_{n+1})^2] \right\rangle
\end{align}

where we assume that all pore radii are larger than the critical radius. We consider now the Laplace transform in $x$ to obtain

\begin{align}
\widetilde p(k) &= \left\langle \sum\limits_{n = 0}^\infty \exp\left(- k \sum\limits_{i = 1}^n \lambda_i\right) \prod\limits_{i = 1}^n \alpha(\lambda_i)
[1 - \alpha(\lambda_{n+1})] \right\rangle
\nonumber\\
&= \left\langle \sum\limits_{n = 0}^\infty \prod\limits_{i = 1}^n \exp\left(- k \lambda_i\right)  \alpha(\lambda_i)
[1 - \alpha(\lambda_{n+1})] \right\rangle
\nonumber\\
&= \sum\limits_{n = 0}^\infty \prod\limits_{i = 1}^n \left\langle \exp\left(- k
\lambda_i\right) \alpha(\lambda_i) \right\rangle
\left\langle [1 - \alpha(\lambda_{n+1})] \right\rangle
\nonumber\\
&= \sum\limits_{n = 0}^\infty \left\langle \exp\left(- k
\lambda\right) \alpha(\lambda) \right\rangle^n
\left\langle [1 - \alpha(\lambda)] \right\rangle
\nonumber\\
&= \frac{\left\langle [1 - \alpha(\lambda)] \right\rangle}{1 - \left\langle \exp\left(- k
\lambda\right)  \alpha(\lambda)\right\rangle}
\end{align}

We need to determine

\begin{align}
F(k)&\equiv \left\langle \exp\left(- k \lambda\right)  \alpha(\lambda)\right\rangle =
\int\limits_{0}^\infty d y p_\lambda(y) \exp\left(- k y\right)  \alpha(y)
\end{align}

in order to understand the $k$-dependence of $\widetilde p(k)$. The pore length distribution $p_\lambda(y)$ is given by the Gamma distribution,

\begin{align}
\label{eq:gamma}
p_\lambda(y) = \left(\frac{y}{\ell_0}\right)^{\beta-1}
\frac{\exp(-y/\ell_0)}{\Gamma(\beta) \ell_0}.
\end{align}

Thus, we obtain for $F(k)$

\begin{align}
F(k) & =
\int\limits_{0}^\infty d y \left(\frac{y}{\ell_0}\right)^{\beta-1}
\frac{\exp(-y/\ell_0)}{\Gamma(\beta) \ell_0} \exp\left(- k y\right)
\alpha(y)
=
\int\limits_{0}^\infty d y \left(\frac{y}{\ell_0}\right)^{\beta-1}
\frac{\exp[-y (k + 1/\ell_0]}{\Gamma(\beta) \ell_0}  \alpha(y),
\end{align}

where $\beta = 0.4$.  This shows that $F(k) = G(k+1/\ell_0)$, that is, it is a function of $k+1/\ell_0$. This implies that $p(x)$ decays exponentially fast for $x > \ell_0$. Figure~\ref{fig} shows the distribution of flight distances for the Gamma distribution~\ref{eq:gamma} with $\beta = 0.4$ and $\ell_0 = 1$.

